def signing(SK, msg, t):
    b_list, commit_curves = sample_ephemeral_randoms(t)
    c_list = derive_challenges(msg, commit_curves, t)
    responses = compute_responses(SK , b_list, c_list)
    return {
        "c": c_list,
        "r": responses
    }

